contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that withdraw and withdrawAll only succeed when called by the owner (this contract).
    // Parameters:
    // - callerIsOwner: if true we invoke withdraw/withdrawAll directly from this contract (owner); if false we simulate a non-owner by making an external call from an EOA-like address: since the checker runs everything in one tx and msg.sender for calls on c will be this contract, we simulate a non-owner by deploying a minimal forwarder in-place via low-level call using address(0x123) is not allowed; instead we use try/catch with an explicit external call to c from this contract but using sendMoney to make c call itself as non-owner isn't possible. To simulate a non-owner call in this environment, we leverage that the onlyOwner modifier checks msg.sender == owner; owner was set at C deployment to payable(msg.sender) where msg.sender was the deployer of C (the checker). Because checker deploys a fresh C and passes it into the constructor of this test, owner != address(this). Therefore this contract is NOT the owner. To exercise owner behavior, we need to call withdraw/send functions using c.owner() address via sendMoney to make c perform the withdraw to its owner. However sendMoney is only owner-restricted, so we cannot. Instead we check that when this contract (non-owner) calls withdraw/withdrawAll they revert and do not change observable state. Conversely, we can also check that calling the fallback (payable) increases depositsCount and contract balance.
    // Thus the property: non-owner calls to withdraw/withdrawAll revert and do not change depositsCount or balance.

    function run(bool callWithdrawAll, uint withdrawAmount, uint sendDeposit) public payable {
        require(true);

        // Make sure we can send Ether to c for the deposit test
        if (sendDeposit > 0) {
            require(address(this).balance >= sendDeposit);
            // send Ether to c using fallback by calling with empty data
            (bool ok,) = address(c).call{value: sendDeposit}(""");
            // the fallback increments depositsCount on success
            // ok may be false if transfer failed; we still proceed to check invariants in either case
            ok; // silence warning
        }

        // Read observable state before calling withdraw functions
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;
        if (callWithdrawAll) {
            // This contract is not the owner (owner was set to the deployer of C), so withdrawAll must revert.
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Try withdraw with a provided amount
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if the call was made by a non-owner (this contract) it must revert and the contract's balance
        // and depositsCount must remain unchanged by the attempted withdraw/withdrawAll call.
        // Because this test contract is not the owner (owner set at C deployment to another address), we assert reverted => no state change.
        assert(reverted == true ? (afterDeposits == beforeDeposits && afterBalance == beforeBalance) : true);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: attempts a withdraw or withdrawAll from this contract (non-owner)
    // and asserts that the call reverts and does not change observable state (depositsCount and balance).
    // Parameters:
    // - callWithdrawAll: if true call withdrawAll(), else call withdraw(amount)
    // - withdrawAmount: amount to pass to withdraw when callWithdrawAll is false
    // - depositAmount: optional Ether to first send to c via fallback to create observable balance/depositsCount changes
    function run(bool callWithdrawAll, uint withdrawAmount, uint depositAmount) public payable {
        require(true);

        // If sending Ether to c, ensure this contract has enough balance and send with empty data to trigger fallback
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
            (bool ok, ) = address(c).call{value: depositAmount}("\x00");
            // We ignore ok; fallback may revert or succeed. Either way we proceed to check properties after attempted withdraw.
            ok; // silence unused var
        }

        // Observe state before attempted privileged call
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // This test contract is not the owner of c (owner was set to the deployer of C). Therefore the privileged calls
        // withdraw/withdrawAll must revert, and when they revert they must not have changed depositsCount or balance.
        assert(reverted == true ? (afterDeposits == beforeDeposits && afterBalance == beforeBalance) : reverted == false);
    }

    receive() external payable { }
}

