contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = address(this);
    }

    // params: callerAddress is an external address that will attempt the call by using call();
    // amount is Ether to send to c via its fallback to increase depositsCount and balance before the test.
    function run(address caller, uint amount, uint sendValue, bytes memory data) public payable {
        require(address(this).balance >= amount + sendValue, "insufficient balance for test");

        // 1) Fund c by sending Ether to its fallback so balance and depositsCount may change.
        // The contract's fallback increments depositsCount; we fund with `amount`.
        c.f{value: amount}("\x00"); // This will trigger fallback and increase depositsCount

        // read balance before the attack attempt
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Now simulate a call from an address `caller` that is NOT the owner (owner is deployer == this contract)
        // We cannot change msg.sender inside this contract for calls to c, but we can perform low-level call from
        // the externally supplied `caller` by using address(c).call with encoded selector of sendMoney/withdraw.
        // However, msg.sender in c will be this contract for any calls we perform here. To test non-owner behavior,
        // we perform a low-level call via address(c).call but set the from by using a plain external call: that is not possible.
        // Instead, we check that calls that should be owner-only revert when invoked from this contract if this contract is not owner.
        // But this contract is the owner (it deployed c). To test non-owner, we make a call through address(c).call with a forged sender
        // by using a call to a contract at `caller` which then calls c. We implement that inline by assuming `caller` is a contract
        // that will forward the call. Since we cannot deploy new contracts here, require that caller != address(this) and that caller is a contract
        // is not enforceable. To keep within constraints, we instead assert the following invariant which must hold for owner: when owner
        // calls withdraw/sendMoney, c's balance decreases appropriately and sender receives Ether. We will therefore perform the owner call
        // and assert the balance change matches the withdraw amount.

        // Make an owner withdraw attempt: withdraw(sendValue)
        // Ensure sendValue is not greater than balance to avoid revert due to transfer failure
        if (sendValue > balBefore) {
            sendValue = balBefore;
        }

        // Call withdraw as owner (this contract is owner). Catch revert
        bool reverted;
        try c.withdraw(sendValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // Assert general rule: if withdraw did not revert, c's balance decreased exactly by sendValue and depositsCount unchanged
        assert((reverted && balAfter == balBefore && depositsAfter == depositsBefore) || (!reverted && balBefore - balAfter == sendValue && depositsAfter == depositsBefore));
    }

    // allow receiving Ether when withdraw transfers to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // sendAmount: amount to fund c via fallback before testing
    // withdrawAmount: amount passed to c.withdraw
    function run(uint sendAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to fund c and possibly receive back
        require(address(this).balance >= sendAmount, "insufficient balance to fund c");

        // 1) Fund c by sending Ether to it so its fallback is triggered (increments depositsCount)
        // Use low-level call to trigger fallback: empty calldata
        (bool fundOk, ) = address(c).call{value: sendAmount}("\x00");
        // funding may succeed or fail; require it succeeds to make meaningful test
        require(fundOk, "funding call failed");

        // read observable state before withdraw
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // prepare to call withdraw as owner (this contract is owner since it deployed c)
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule assertion:
        // If withdraw reverted then balance and depositsCount unchanged.
        // If withdraw succeeded then balance decreased exactly by withdrawAmount and depositsCount unchanged.
        assert(
            (reverted && balAfter == balBefore && depositsAfter == depositsBefore)
            || (!reverted && balBefore >= withdrawAmount && balBefore - balAfter == withdrawAmount && depositsAfter == depositsBefore)
        );
    }

    receive() external payable {}
}

