        // Trigger fallback by calling c with empty calldata and sending Ether; this is a low-level call
        // Use address(c).call{value: ...}("") to invoke fallback
        (bool fundOk, ) = address(c).call{value: fundAmount}("");
        require(fundOk, "funding failed");

        // observe before-values
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // call withdrawAll as owner (this contract is owner because it deployed c)
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

