contract InvMutTest {
    C c;
    address owner;
    constructor(C _c) { c = _c; owner = address(_c); }

    // The test takes parameters to try calling withdraw/withdrawAll/sendMoney and possibly sending value to fallback.
    // We will attempt actions as the InvMutTest contract (which is c's deployer), so it is the owner. To simulate
    // non-owner behaviour we rely on call data that triggers fallback on c via a low-level call from an externally owned account
    // isn't possible here; instead we check that only the owner (this contract) can call withdraw/withdrawAll successfully,
    // and that calls from this contract succeed and change balances as expected.

    function run(address payable target, uint sendToTarget, uint sendToC) public payable {
        require(address(this).balance >= sendToC, "insufficient balance to send to c");

        // Record balances and depositsCount before any operations
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // If requested, send Ether to c to trigger its fallback and increase depositsCount
        if (sendToC > 0) {
            // send Ether to c's fallback
            (bool s,) = address(c).call{value: sendToC}("0x");
            // call may succeed or revert; if it reverts the rest still proceeds, but depositsCount won't increment
            // We don't assert on s here; we will observe depositsCount change
        }

        // Owner (this contract) calls withdraw with a value up to c's balance. This should succeed and decrease c's balance.
        uint withdrawAmount = beforeC + sendToC; // attempt to withdraw whole expected balance
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Now call withdrawAll as owner; should succeed and set c balance to zero (unless previous withdraw failed differently)
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Finally, attempt sendMoney to a target address with zero data and zero value as owner; should succeed or revert depending on target
        bool sendMoneyReverted;
        try c.sendMoney(target, sendToTarget, "") {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after state
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // If owner calls withdraw or withdrawAll did not revert, then c's balance must be <= beforeC + sendToC and depositsCount must be >= beforeDeposits.
        // Additionally, depositsCount never decreases.
        assert((!withdrewReverted || !withdrewAllReverted) ? (afterC <= beforeC + sendToC && afterDeposits >= beforeDeposits) : (afterDeposits >= beforeDeposits));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // sendToC: amount of wei to send to c to trigger fallback (can be 0)
    // withdrawAmount: amount owner will attempt to withdraw via withdraw
    // sendToTarget and data for sendMoney are not used in this property but could be passed; keep minimal inputs
    function run(uint sendToC, uint withdrawAmount) public payable {
        // Ensure this contract has enough balance to send sendToC
        require(address(this).balance >= sendToC, "insufficient balance for sendToC");

        // Observe before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeCbal = address(c).balance;

        // Send Ether to c to trigger fallback (this may increment depositsCount)
        (bool sent, ) = address(c).call{value: sendToC}("0x");
        // We don't require sent: fallback might revert for some reason, but depositsCount should not decrease.

        // Owner (this contract, deployer of c) attempts to withdraw withdrawAmount
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Owner attempts withdrawAll
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Observe after-values
        uint afterDeposits = c.depositsCount();
        uint afterCbal = address(c).balance;

        // General rule:
        // 1) depositsCount never decreases: afterDeposits >= beforeDeposits
        // 2) withdraw and withdrawAll (owner calls) do not increase depositsCount (only fallback can)
        //    i.e., any increase in depositsCount must be due to the earlier sendToC call that triggered fallback.
        // We express 2) as: if sendToC==0 then depositsCount must be unchanged by withdraw/withdrawAll
        // and in general afterDeposits - beforeDeposits <= (sendToC > 0 ? 1 : 0) because single fallback call increments at most once.

        uint deltaDeposits = afterDeposits - beforeDeposits;
        bool atMostOneFromFallback = sendToC > 0 ? (deltaDeposits <= 1) : (deltaDeposits == 0);

        assert(afterDeposits >= beforeDeposits && atMostOneFromFallback);
    }

    // Allow receiving Ether so withdraw transfers can be observed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // sendToC: amount of wei to send to c to trigger fallback (can be 0)
    // withdrawAmount: amount owner will attempt to withdraw via withdraw
    function run(uint sendToC, uint withdrawAmount) public payable {
        require(address(this).balance >= sendToC, "insufficient balance to send to c");

        // Observe before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeCbal = address(c).balance;

        // Perform actions (each c-state-changing call must be a top-level statement)
        // 1) send Ether to c to trigger fallback (may increment depositsCount)
        (bool sent, ) = address(c).call{value: sendToC}("");
        sent; // silence unused warning

        // 2) attempt withdraw by owner (this contract is the deployer/owner)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // 3) attempt withdrawAll by owner
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Observe after-values
        uint afterDeposits = c.depositsCount();
        uint afterCbal = address(c).balance;

        // General rule (single assert):
        // - depositsCount never decreases
        // - neither withdraw nor withdrawAll can increase depositsCount
        //   so any increase is attributable solely to the fallback send above (at most +1)
        // - additionally, if withdraw succeeded then c's balance should not have increased due to it
        //   (i.e., withdraw cannot increase address(c).balance)

        // Express: afterDeposits >= beforeDeposits
        // and (afterDeposits - beforeDeposits) <= (sendToC > 0 ? 1 : 0)
        // and if withdraw succeeded then afterCbal <= beforeCbal + sendToC

        uint deltaDeposits = afterDeposits - beforeDeposits;
        bool atMostOneFromFallback = sendToC > 0 ? (deltaDeposits <= 1) : (deltaDeposits == 0);
        bool withdrawDidNotIncreaseBalance = withdrawReverted ? true : (afterCbal <= beforeCbal + sendToC);

        assert(afterDeposits >= beforeDeposits && atMostOneFromFallback && withdrawDidNotIncreaseBalance);
    }

    receive() external payable {}
}

