        // - if withdraw succeeded, C's balance did not increase compared to before plus what we sent
        bool depositsNotDecreased = afterDeposits >= beforeDeposits;
        bool atMostOneFromFallback = sendToC > 0 ? (afterDeposits - beforeDeposits <= 1) : (afterDeposits == beforeDeposits);
        bool withdrawDidNotIncreaseBalance = withdrawReverted ? true : (afterCbal <= beforeCbal + sendToC);

        assert(depositsNotDecreased && atMostOneFromFallback && withdrawDidNotIncreaseBalance);
    }

    receive() external payable {}
}

