    constructor(C _c) { c = _c; }
    // We accept parameters: target address to call sendMoney on, value to send in sendMoney, data for call,
    // an extra amount to send to C via fallback, and a flag indicating whether the caller should act as owner.
    // Since this contract is the deployer/owner of C, calls from this contract are owner calls.
    function run(address payable externalTarget, uint sendValue, bytes calldata data, uint fallbackAmount, bool makeOwnerCall) public payable {
        require(address(this).balance >= fallbackAmount, "insufficient balance to fund fallback call");
        // Record observable state before interactions
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // First: optionally send Ether to C to trigger fallback (which increments depositsCount).
        // Use a top-level state-changing call on c by sending Ether to its address via call to fallback.
        if (fallbackAmount > 0) {
            // send Ether to c so its fallback() executes
            (bool s1, ) = address(c).call{value: fallbackAmount}("");
            // We don't require success here; fallback is payable so it should succeed when value provided.
            s1; // silence unused warning
        }

        // Now attempt a privileged operation from either owner (this contract) or a non-owner simulated by using a call to c from an external account.
        // We cannot change msg.sender here; but we can detect branch: when makeOwnerCall=true we perform an owner call (this contract);
        // when false we perform a non-owner attempt by invoking a call to c through a forwarded call from msg.sender (the external caller) —
        // however the checker invokes run exactly once, with msg.sender being an EOA, so we simulate non-owner by constructing a call that will revert when not owner.
        // The only way inside this single transaction to have c see a different msg.sender is to have c call back into another contract; we cannot change that.
        // Instead, we check property for owner-call path and non-owner expectation by observing revert for a non-owner attempt using a try/catch on a call from this contract to a helper function on C that will revert when called by non-owner.
        // Because we cannot change msg.sender inside this transaction, we emulate the non-owner attempt by creating a new contract that will call c (this new contract will not be owner) and forwarding the result.

        // Deploy a temporary non-owner caller contract
        NonOwnerCaller nonOwner = new NonOwnerCaller(address(c));

        bool ownerCallReverted;
        bool nonOwnerCallReverted;

        // Owner call: this contract is the owner, so withdrawAll() should succeed (and transfer balance to owner==this contract)
        // But withdrawAll will transfer c's balance to owner (this contract). Capture revert via try/catch
        try c.withdrawAll() {
            ownerCallReverted = false;
        } catch {
            ownerCallReverted = true;
        }

        // Non-owner contract attempts same withdrawAll; it should revert due to onlyOwner modifier
        try nonOwner.doWithdrawAll() {
            nonOwnerCallReverted = false;
        } catch {
            nonOwnerCallReverted = true;
        }

        // Also test sendMoney: owner call from this contract to externalTarget with sendValue and data
        bool ownerSendReverted;
        try c.sendMoney(externalTarget, sendValue, data) {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        // Non-owner caller tries sendMoney and should revert
        bool nonOwnerSendReverted;
        try nonOwner.doSendMoney(externalTarget, sendValue, data) {
            nonOwnerSendReverted = false;
        } catch {
            nonOwnerSendReverted = true;
        }

        // Observe after-state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint thisBalance = address(this).balance;

        // General rule asserted:
        // 1) Owner calls must not revert (ownerCallReverted == false) and non-owner calls must revert (nonOwnerCallReverted == true).
        // 2) After owner withdrawAll, c.balance should be less-or-equal than before (funds moved out); After non-owner failed attempts, c.balance unchanged from before for those operations.
        // 3) depositsCount only changed by fallbackAmount > 0 path and equals before + (fallbackAmount>0?1:0)
        bool depositsIncCorrect = (afterDeposits == beforeDeposits + (fallbackAmount > 0 ? 1 : 0));
        // For balances: if ownerCallReverted==false then afterBalance <= beforeBalance
        bool ownerWithdrawBalanceOk = ownerCallReverted ? true : (afterBalance <= beforeBalance);
        // Non-owner attempts must revert, so they should not change balance: since they ran in separate contracts and reverted, c.balance unchanged by them.
        // We only assert that nonOwnerCallReverted and nonOwnerSendReverted are true.

        assert(depositsIncCorrect && ownerCallReverted == false && nonOwnerCallReverted == true && ownerSendReverted == false && nonOwnerSendReverted == true && ownerWithdrawBalanceOk);
    }

    receive() external payable {}
}

