        // 1) send Ether to c via fallback to increase its balance and depositsCount
        // calling fallback: send value with empty data
        c.f{value: amount}();

        // record balance and depositsCount after deposit
        uint balAfterDeposit = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // 2) owner (this contract) tries to withdraw some value (take half, but avoid underflow)
        uint withdrawValue = amount / 2;
        bool ownerReverted;
        try c.withdraw(withdrawValue) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        uint balAfterOwnerWithdraw = address(c).balance;

        // 3) Now simulate an attacker (external address) attempting to call withdraw via .call
        // Because this test contract is the owner, any direct call from here is owner-call; to simulate attacker
        // we perform a low-level call to c with msg.sender set to this contract -> cannot change sender in solidity.
        // Instead we assert that withdraw when called by non-owner must revert by using try/catch on a call made
        // through the contract's sendMoney (which enforces onlyOwner). We'll have the attacker address be used as
        // target for sendMoney to try and trigger non-owner withdrawal incorrectly. We attempt to make c send funds
        // to attacker by calling sendMoney with _target = attacker; this is still an owner-only call, so this call
        // should succeed only when invoked by owner (this contract). The actual property we can assert reliably is:
        // - If owner withdraw did not revert then balance decreased by withdrawValue; otherwise balance unchanged.

        // Attempting an attacker withdraw directly from this contract is impossible because msg.sender is fixed.
        // So we only assert the observable invariant about owner withdraw effect and depositsCount increment.

        // final assert: depositsCount increased by 1 and if owner withdraw succeeded then balance decreased by withdrawValue
        assert(depositsAfter == c.depositsCount() &&
               depositsAfter >= 1 &&
               (ownerReverted ? (balAfterOwnerWithdraw == balAfterDeposit) : (balAfterOwnerWithdraw + withdrawValue == balAfterDeposit))
        );
    }

