        // its fallback, forwarding the provided value. We must ensure the invoked call sends the intended Ether amount.

        // Ensure this contract has enough balance to pass to c.sendMoney
        require(address(this).balance >= sendAmount, "insufficient balance for sendMoney transfer");

        // Call sendMoney on c to cause c to call itself with value sendAmount and empty data, which triggers fallback on c
        c.sendMoney(address(c), sendAmount, "");

