    constructor(C _c) { c = _c; }

    // Attempt to withdraw a given amount from c; ensure this contract (the owner) can call withdraw
    // and that calling withdraw does not change depositsCount (withdraw should not touch depositsCount).
    function run(uint withdrawAmount) public payable {
        // no precondition on withdrawAmount; this contract is the owner by construction

        // read before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // try withdraw and capture whether it reverts
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: since this contract is the owner, withdraw must NOT revert, and withdraw does not change depositsCount.
        // Also, if withdraw succeeded then c.balance is either reduced by withdrawAmount (bounded by available balance)
        // or reduced to zero if withdrawAmount > beforeBal; express as: if not reverted, afterBal + withdrawAmount == beforeBal
        // but to avoid underflow when withdrawAmount > beforeBal, we instead assert that afterBal <= beforeBal
        // and if withdrawAmount <= beforeBal then afterBal == beforeBal - withdrawAmount.
        assert(
            reverted == false
            && afterDeposits == beforeDeposits
            && afterBal <= beforeBal
            && (withdrawAmount > beforeBal || afterBal == beforeBal - withdrawAmount)
        );
    }

    // allow receiving ETH when c sends funds to this contract during withdraw
    receive() external payable {}
}

