            try c.sendMoney(address(c), amount, empty) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // amount == 0 is allowed too; still invoke sendMoney which will call target.call with 0 value and empty data
            try c.sendMoney(address(c), 0, empty) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

