        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if the inner call succeeded (not reverted), then depositsCount increments by 1 and balance increases by amount;
        // if it reverted, both remain unchanged.
        assert(
            (!reverted && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
            || (reverted && afterCount == beforeCount && afterBal == beforeBal)
        );
    }

    receive() external payable {}
}

