contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target address, amount to send, arbitrary calldata
    function run(address target, uint amount, bytes calldata data) public payable {
        // We must be owner (this contract is owner by construction). Ensure we have funds to send.
        require(address(this).balance >= amount);

        // Observe before
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Top-level state-changing call
        try c.sendMoney(target, amount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // Determine if target is a contract by checking its code size via extcodesize-like behavior:
        // We cannot call extcodesize directly here, but we can rely on observable effects: when sending to an EOA,
        // C.sendMoney will call target.call which will succeed (unless target reverts in fallback) and NOT trigger C.fallback.
        // For a general, provable invariant we assert: if sendMoney succeeded and the target is NOT the contract itself,
        // then depositsCount did not change (i.e., only calls that target the contract itself can trigger fallback increments).
        // Because we cannot directly test "target is non-contract", we instead require the target != address(c) in the precondition
        // so that the property quantifies over non-self targets.
        require(target != address(c));

        // General rule: For any non-self target, either sendMoney reverts leaving depositsCount and balance unchanged,
        // or it succeeds and depositsCount remains unchanged while the contract balance decreased by amount.
        assert((reverted && afterCount == beforeCount && afterBal == beforeBal) || (!reverted && afterCount == beforeCount && afterBal + amount == beforeBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run takes a uint amount and a boolean flag chooseWithdrawAll to decide which function to call
    // msg.sender for calls to c will be this contract (the owner), but we need to simulate a non-owner call.
    // To simulate a non-owner call, we deploy a small helper via create2 is not allowed; instead we rely on the fact
    // the checker will call run(...) from arbitrary accounts: but per constraints, the checker runs run exactly once
    // with msg.sender being the InvMutTest contract's deployer? Actually the problem statement: "msg.sender is the InvMutTest contract for every call on c, and this contract deployed c."
    // Therefore to exercise non-owner behavior we must make a call that originates from some other EOA. We can achieve that by
    // using c.sendMoney to make c call back into this contract, which can then try to call withdraw as a different caller via a reentrant external call.
    // However those approaches are complex. Simpler: assert a universal implication that if a call from THIS contract (owner) to withdraw or withdrawAll() does NOT revert
    // then owner must be equal to address(this). But that repeats owner logic. Instead, we can check that any attempt by this contract to call withdraw(uint) succeeds only when it is owner — since this contract is the owner (deployer), calls should succeed. To create a non-owner call, we use the fact that c.owner is public; we'll check that if owner != address(this) then calls revert and state unchanged.
    // So the input allows changing c.owner by sending the contract through its fallback: but owner is immutable except set at construction. Given constraints, we instead write the general rule:
    // For any caller (simulated by a parameter `attemptingIsOwner`): if a call is made (we only can make calls from this contract) then it must satisfy that if c.owner() != address(this) then a withdraw(uint) or withdrawAll() call attempted from here reverts and does not change balance or depositsCount. We perform the call and record effects.
    function run(uint amount, bool useWithdrawAll) public payable {
        // Precondition: ensure we have enough ETH if we will try to send into c for setup
        // We may fund c by sending Ether via fallback by calling c with empty calldata which triggers fallback and increments depositsCount.
        // To ensure some balance, optionally send 'amount' into c via fallback. Require we have balance for that.
        if (amount > 0) {
            require(address(this).balance >= amount);
            // send Ether to C triggering fallback
            (bool s,) = address(c).call{value: amount}("0x");
            // fallback increments depositsCount on each payable call, and will accept ether
            // ignore success; if it failed, nothing changed
        }

        // read pre-state
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address ownerBefore = c.owner();

        bool reverted;
        if (useWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if c.owner() is not this contract, then any withdraw/withdrawAll call from this contract must revert,
        // and balances and depositsCount must remain unchanged. Conversely, if owner is this contract and the call did not revert,
        // then contract balance must not increase and depositsCount must be unchanged. We capture the first direction as required property
        // (the converse is already among accepted rules). We assert the implication for the non-owner case.
        assert(
            (ownerBefore != address(this)) ? (reverted && afterBal == beforeBal && afterDeposits == beforeDeposits) : true
        );
    }

    receive() external payable { }
}

